export const REGION_TYPES={BR:'Estados e Distrito Federal',US:'Estados e Distrito de Columbia',PT:'Distritos e regiões autônomas',ES:'Comunidades e cidades autônomas',IT:'Regiões',GB:'Nações constituintes',DE:'Estados federados',NL:'Províncias e municípios caribenhos',IE:'Condados',CH:'Cantões',AT:'Estados federados'};
const normalize=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
export const REGIONS=Object.fromEntries(Object.entries(catalog).map(([country,text])=>[country,text.split(';').map(row=>{const [code,name,...aliases]=row.split('|');return {code,name,aliases};}).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))]));
const regionLookup=Object.fromEntries(Object.entries(REGIONS).map(([country,regions])=>[country,new Map(regions.flatMap(r=>[r.code,`${country}-${r.code}`,r.name,...r.aliases].map(alias=>[normalize(alias),r.code])))]));
export function resolveRegion(country,value){const raw=normalize(value);if(!raw)return '';const cleaned=raw.replace(/^(state of|estado de|estado do|distrito de|district of|county|co|condado de|canton of|kanton) /,'');return regionLookup[country]?.get(raw)||regionLookup[country]?.get(cleaned)||'';}
export const leadRegion=l=>resolveRegion(l?.country_code||'BR',l?.state);
export const regionName=(country,code)=>REGIONS[country]?.find(r=>r.code===code)?.name||'Sem região definida';
export const regionMatches=(lead,region)=>!region||(region==='unassigned'?!leadRegion(lead):leadRegion(lead)===region);
export function regionOptions(country,selected='',empty='Sem região definida'){const escape=v=>String(v).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');return `<option value="">${escape(empty)}</option>`+(REGIONS[country]||[]).map(r=>`<option value="${r.code}" ${r.code===selected?'selected':''}>${escape(r.name)}</option>`).join('');}
